        private void SeedPayments(ModelBuilder modelBuilder)
        {
            // ProviderTransactionId values here are placeholders, not real Stripe PaymentIntent
            // ids — fine for exercising GetAll/GetById/filtering, but calling the real
            // /Payments/{id}/refund action against one of these will fail against Stripe's API
            // since it doesn't recognize a "pi_seed_..." id. Covers every PaymentStatus: Paid,
            // Refunded, Pending, and Failed — plus appointments with no Payment row at all
            // (pay-at-clinic / not-yet-initiated variant).
            modelBuilder.Entity<Payment>().HasData(
                new { Id = 1, AppointmentId = 1, Amount = 40.00m, Status = PaymentStatus.Paid, ProviderTransactionId = "pi_seed_0001", PaidAt = (DateTime?)new DateTime(2026, 8, 20, 9, 5, 0, DateTimeKind.Utc), RefundedAmount = (decimal?)null, RefundedAt = (DateTime?)null, CreatedAt = new DateTime(2026, 8, 20, 9, 0, 0, DateTimeKind.Utc) },
